package i18n

// helpCatalog は wx の help 本文である。段落・オプション 1 行ごとに message ID を持ち、
// コマンド名・オプション名・path などの機械識別子は cmd/wx 側が原文のまま出す。
var helpCatalog = map[string]Entry{
	"help.usage":                    {EN: "Usage:", JA: "使い方:"},
	"help.top.p1":                   {EN: "Global options:", JA: "全体オプション:"},
	"help.top.branch":               {EN: "choose a detached base (repeatable)", JA: "detached base を選択（複数指定可）"},
	"help.top.fresh":                {EN: "resume conversation from the current base", JA: "現在の base から会話を再開"},
	"help.top.select_worktree":      {EN: "select and save the workspace policy again", JA: "workspace 方針を再選択して保存"},
	"help.top.worktree":             {EN: "create a worktree without saving a policy", JA: "方針を保存せず worktree を作成"},
	"help.top.no_worktree":          {EN: "run here without saving a policy", JA: "方針を保存せずここで実行"},
	"help.top.help":                 {EN: "show help", JA: "ヘルプを表示"},
	"help.top.version":              {EN: "show version", JA: "バージョンを表示"},
	"help.top.p2":                   {EN: "Commands:", JA: "コマンド:"},
	"help.top.claude":               {EN: "launch Claude Code in a wx workspace", JA: "wx workspace で Claude Code を起動"},
	"help.top.codex":                {EN: "launch Codex in a wx workspace", JA: "wx workspace で Codex を起動"},
	"help.top.shell":                {EN: "open a shell in a wx workspace", JA: "wx workspace で shell を開く"},
	"help.top.run":                  {EN: "run one command in a wx workspace", JA: "wx workspace でコマンドを1つ実行"},
	"help.top.new":                  {EN: "lease a workspace and print its path", JA: "workspace を貸し出し、その path を表示"},
	"help.top.release":              {EN: "return a leased workspace now", JA: "貸出中の workspace を直ちに返却"},
	"help.top.status":               {EN: "show daemon and pool state", JA: "daemon と pool の状態を表示"},
	"help.top.doctor":               {EN: "check configuration, dependencies, worktrees", JA: "設定・依存関係・worktree を検査"},
	"help.top.gc":                   {EN: "run retention cleanup", JA: "保持期間に基づく整理を実行"},
	"help.top.prune":                {EN: "delete recovery refs the database cannot explain", JA: "database が説明できない復旧 ref を削除"},
	"help.top.clear":                {EN: "delete managed worktrees now", JA: "管理 worktree を直ちに削除"},
	"help.top.retry_standby":        {EN: "resume standby replenishment after it stopped", JA: "停止した standby 補充を再開"},
	"help.top.slots":                {EN: "list managed wx slots and their disk usage", JA: "管理 wx slot とディスク使用量を一覧表示"},
	"help.top.bench":                {EN: "measure how long a workspace takes to prepare", JA: "workspace の準備にかかる時間を計測"},
	"help.top.config":               {EN: "show or update configuration", JA: "設定を表示または更新"},
	"help.top.setup":                {EN: "review and complete, or remove, the wx setup", JA: "wx setup を確認して完了、または削除"},
	"help.top.resume":               {EN: "restore a wx session", JA: "wx session を復元"},
	"help.top.discard_recovery":     {EN: "discard recovery state that lost its refs", JA: "ref を失った復旧状態を破棄"},
	"help.top.forget":               {EN: "stop managing a workspace", JA: "workspace の管理を解除"},
	"help.top.daemon":               {EN: "change whether the daemon is running", JA: "daemon の稼働状態を変更"},
	"help.top.daemon2":              {EN: "register or remove the LaunchAgent", JA: "LaunchAgent を登録または削除"},
	"help.status.p1":                {EN: "Show a workspace summary, or all daemon, pool, session, retention, and disk\ndetails with --verbose (-v). The JSON shape is unchanged by either display.", JA: "workspace の要約、または daemon・pool・session・retention・disk の全詳細を表示\n詳細は --verbose (-v) で表示します。どちらの表示でも JSON の形状は変わりません。"},
	"help.status.p2":                {EN: "The summary lists the workspaces whose POLICY creates worktrees (HOT or COLD)\nand any workspace that still holds one. A workspace that neither uses nor holds\na worktree is left to --verbose and --json.", JA: "要約には POLICY が worktree（HOT または COLD）を作成する workspace\nと、worktree を保持している workspace を一覧表示します。どちらも該当しない workspace は\n--verbose と --json の場合だけ表示します。"},
	"help.status.p3":                {EN: "Disk reports what the managed slots and snapshots occupy on their own: blocks\nthey still share with the main worktrees are excluded, so it sums with the\nSIZE(MB) column of wx slots and stays below what du reports. Paths outside the\ndatabase are listed separately as Unmanaged. --verbose adds the full allocated\nsize and the shared part behind it.", JA: "Disk は管理 slot と snapshot が単独で占める容量を示します。\nmain worktree と共有している block は除外するため、\nSIZE(MB) wx slots の列と合計でき、du より小さくなります。\ndatabase 外の path は Unmanaged として別に表示します。--verbose では割当全体と\n共有部分も追加表示します。"},
	"help.status.p4":                {EN: "Options:", JA: "オプション:"},
	"help.status.verbose":           {EN: "show detailed status instead of the summary", JA: "要約の代わりに詳細な状態を表示"},
	"help.status.json":              {EN: "print machine-readable JSON", JA: "機械可読 JSON を表示"},
	"help.doctor.p1":                {EN: "Run read-only checks for configuration, storage, Git, launchd, hooks, and recovery data.\nPrint one line when nothing is wrong; otherwise report each problem with its target, cause, and action.\nExit 0 when only passing and informational results remain, 1 when a problem or an unfinished check remains.", JA: "設定、storage、Git、launchd、hook、復旧データを読み取り専用で検査します。\n問題がなければ1行、問題があれば対象・原因・対処とともに報告します。\n正常または情報だけなら終了コード0、問題または未完了の検査があれば1で終了します。"},
	"help.doctor.p2":                {EN: "Without --probe no worktree is created, so a workspace that prepares a worktree\nwx cannot actually work in is not detected. With --probe wx leases one workspace\nat a time, waits for EARLY READY and then FULL READY, and inspects what it got:\nsubmodules the index records but whose directory stayed empty, tracked files\nalready modified in a worktree wx just prepared, output a post-checkout hook\nwrote while still exiting 0, and whether the copy shared blocks with the main\nworktrees. It also reports how long each workspace took and what the prepared\nslot occupies per repository. Every probed workspace is returned without saving\nit, as wx release --discard does.", JA: "--probe なしでは worktree を作成しないため、worktree の準備が必要な workspace が\n実際には動作できないことを検出できません。--probe では workspace を1つずつ貸し出し、\nEARLY READY、続いて FULL READY まで待ち、取得した内容を検査します。\nindex が記録しているのにディレクトリが空のままの submodule、wx が準備した worktree ですでに変更された tracked file、終了コード0のまま post-checkout hook が書き込んだ出力、copy が main worktree と block を共有したかを検査します。workspace ごとの所要時間と、準備した slot が repository ごとに占める容量も表示します。検査した workspace は wx release --discard と同じく保存せず返却します。"},
	"help.doctor.p3":                {EN: "--probe first retires the standby worktrees waiting for each workspace so what\nit measures is a cold start. They are reclaimed by normal GC and replenished\nafterwards, so starting a session in a probed workspace is slower until then.\nIt runs one workspace at a time and takes as long as preparing every registered\nworkspace does. Interrupting it skips the return of the workspace being probed,\nwhich then stays leased until the wx session that ran the command ends, or until\nlease.ttl.", JA: "--probe は各 workspace の待機中 standby worktree を先に退役させるため、\ncold start を計測します。これらは通常の GC で回収され、その後補充されます。\nその後に補充されるため、検査した workspace で session を始めると補充が終わるまで遅くなります。1 workspace ずつ実行し、登録済み全 workspace の準備と同じだけ時間がかかります。中断すると検査中の workspace は返却されず、コマンドを実行した wx session の終了または lease.ttl まで貸出中のままです。"},
	"help.doctor.p4":                {EN: "Options:", JA: "オプション:"},
	"help.doctor.probe":             {EN: "prepare a worktree in every registered workspace and check it", JA: "登録済み各 workspace で worktree を準備して検査"},
	"help.doctor.verbose":           {EN: "show passing checks, informational results, and extra diagnostics", JA: "成功した検査、情報、追加の診断を表示"},
	"help.doctor.json":              {EN: "print machine-readable JSON with every result regardless of --verbose", JA: "機械可読 JSON を表示 --verbose に関係なく全結果を"},
	"help.gc.p1":                    {EN: "Run retention cleanup without deleting unarchived workspace data.", JA: "未アーカイブの workspace データを削除せず保持期間の整理を実行します。"},
	"help.gc.p2":                    {EN: "Options:", JA: "オプション:"},
	"help.gc.dry_run":               {EN: "report candidates without removing them", JA: "削除せず候補を報告"},
	"help.prune.p1":                 {EN: "Delete the recovery refs that the current database no longer explains. These\nare left behind when the state database is rebuilt, and the daemon reports\nthem once per repository.", JA: "現在の database が説明できない復旧 ref を削除します。 state database の再作成時に残され、daemon が repository ごとに一度報告する ref です。"},
	"help.prune.p2":                 {EN: "By default wx deletes only the refs it can prove are safe to lose: every\nobject they reach is also reachable from another ref, so nothing is lost. A\nref that keeps objects of its own is left alone and reported with the number\nof objects that would become unreachable.", JA: "既定では、失って安全だと証明できる ref だけを wx が削除します。ref が到達する全 object が別の ref からも到達できるため、作業は失われません。固有の object を保持する ref は残し、到達不能になる object 数を報告します。"},
	"help.prune.p3":                 {EN: "With --all those refs are deleted too, and the work saved in them is lost for\ngood. Refs the current database still expects are never touched, with or\nwithout --all.", JA: "--all ではそれらの ref も削除され、保存された作業は完全に失われます。現在の database が必要とする ref は --all の有無にかかわらず変更しません。"},
	"help.prune.p4":                 {EN: "Exit status is 0 when the run finished, 1 when something failed, and 2 for an\nargument error. Keeping refs that could not be proven safe is not a failure.", JA: "実行完了時は終了コード0、失敗時は1、引数エラー時は2です。安全に削除できると証明できない ref を残しても失敗ではありません。"},
	"help.prune.p5":                 {EN: "Options:", JA: "オプション:"},
	"help.prune.all":                {EN: "delete refs whose contents cannot be proven safe to lose,\ndiscarding the work they hold", JA: "失って安全だと証明できない ref を削除し、\n保持している作業を破棄"},
	"help.prune.dry_run":            {EN: "report what would be deleted, changing nothing", JA: "削除対象を報告し、何も変更しない"},
	"help.clear.p1":                 {EN: "Delete the worktrees wx manages without waiting for their retention period.\nWork is saved first: recovery data, session history, and workspace\nregistrations stay, and their retention follows the existing settings.", JA: "保持期間を待たずに wx の管理 worktree を削除します。\n最初に作業を保存します。復旧データ、session 履歴、workspace 登録は残り、保持期間は既存設定に従います。"},
	"help.clear.p2":                 {EN: "Standby worktrees waiting for the next session are kept unless --standby or\n--all is given. Once they are deleted, wx does not replenish them until the\naffected workspace is used again.", JA: "次の session を待つ standby worktree は --standby または --all を指定しない限り残します。削除すると、その workspace が再び使われるまで wx は補充しません。"},
	"help.clear.p3":                 {EN: "Without --all, sessions that are in use are left alone. With --all, wx asks\nthose sessions to stop, waits up to 30s for each of them, and deletes only the\nones that stopped; nothing is killed.", JA: "--all なしでは使用中の session を残します。--all では session に停止を求め、各 session を最大30秒待って、停止したものだけを削除します。強制終了はしません。"},
	"help.clear.p4":                 {EN: "Quarantined slots are deleted in every mode, without waiting out\nretention.quarantined. Database registration authorizes deletion, including slots with\nmissing identity records or changed markers, locks, and HEAD. Unregistered\ndirectories are left alone. With --discard, unfinished work is deleted without\nrequiring a successful snapshot. Sessions in use still require --all.", JA: "隔離された slot は全モードで retention.quarantined を待たずに削除します。database の登録が削除を認可するため、identity record、marker、lock、HEAD が変わった slot や欠落した slot も対象です。未登録の directory は残します。--discard では snapshot 成功を待たず未完了の作業を削除します。使用中 session には引き続き --all が必要です。"},
	"help.clear.p5":                 {EN: "The command waits for every target to finish. Interrupting it does not stop\nthe daemon, and running it again rejoins the clear already in progress. While\na clear runs, new sessions and resumes are refused.", JA: "全対象の完了を待ちます。中断しても daemon は停止せず、再実行すると進行中の clear に再参加します。clear 中は新しい session と resume を拒否します。"},
	"help.clear.p6":                 {EN: "Exit status is 0 when every target succeeded or there was nothing to do, 1\nwhen something failed, was quarantined, or did not finish, and 2 for an\nargument error. Keeping sessions in use or standby worktrees is not a failure.", JA: "全対象が成功または対象なしなら終了コード0、失敗・隔離・未完了があれば1、引数エラーなら2です。使用中 session や standby worktree を残しても失敗ではありません。"},
	"help.clear.p7":                 {EN: "Options:", JA: "オプション:"},
	"help.clear.all":                {EN: "ask sessions in use to stop, then delete what stopped, standby\nworktrees included", JA: "使用中 session に停止を求め、停止したものを削除（standby\nworktree を含む）"},
	"help.clear.discard":            {EN: "delete selected worktrees without saving unfinished work", JA: "未完了の作業を保存せず選択した worktree を削除"},
	"help.clear.standby":            {EN: "delete standby worktrees too", JA: "standby worktree も削除"},
	"help.clear.dry_run":            {EN: "report the targets and the reasons wx cannot process some of\nthem, changing nothing", JA: "対象と、wx が処理できない理由を報告し、\n何も変更しない"},
	"help.retry_standby.p1":         {EN: "Resume automatic standby worktree replenishment for a workspace after wx\nstopped it, then retry replenishment in the current generation. Replenishment\nalso resumes on its own once wx claude or wx codex succeeds for the workspace.\nStandby worktrees that failed to prepare still fill the warm count, so\nretry-standby schedules them for removal before it replenishes.\nQuarantined worktrees are left untouched; wx gc deletes them once\nretention.quarantined has passed, and wx clear deletes them right away.", JA: "wx が停止した workspace の standby worktree 自動補充を再開し、\n現在の世代で補充を再試行します。 wx claude または wx codex が workspace で成功すると補充も自動的に再開します。準備に失敗した standby worktree も warm count を占めるため、retry-standby は補充前に削除を予約します。隔離された worktree は変更せず、retention.quarantined 経過後は wx gc が、直ちに削除する場合は wx clear が処理します。"},
	"help.retry_standby.p2":         {EN: "The workspace path is shown by wx status when standby replenishment is stopped.", JA: "standby 補充が停止した場合、workspace path は wx status で確認できます。"},
	"help.retry_standby.p3":         {EN: "Options:", JA: "オプション:"},
	"help.retry_standby.all":        {EN: "resume every workspace whose replenishment stopped and whose\nconfiguration still replenishes", JA: "resume every workspace whose replenishment stopped and whose\nconfiguration still replenishes"},
	"help.config.p1":                {EN: "Show effective configuration, or atomically update one supported scalar key or list.\nUse --describe to show a key's type, scopes, choices, purpose, and impact.", JA: "実効設定を表示するか、対応する scalar key または list を1件 atomically 更新します。\n--describe で key の型、scope、選択肢、目的、影響を表示します。"},
	"help.config.p2":                {EN: "--add and --remove take a list key such as discovery.exclude, readiness.early_paths,\nworkspace copy/link, or sessions.paths.<claude|codex>.sessions, depending on scope.\n--reset takes any list or scalar key wx config lists; it drops the key from the file\nso the inherited or built-in default applies again.", JA: "--add and --remove take a list key such as discovery.exclude, readiness.early_paths,\nworkspace copy/link, or sessions.paths.<claude|codex>.sessions, depending on scope.\n--reset takes any list or scalar key wx config lists; it drops the key from the file\nso the inherited or built-in default applies again."},
	"help.config.p3":                {EN: "Config v2 uses explicit scopes: --system, --workspace-defaults,\n--repository-defaults, --workspace <root>, or --workspace <root> together with\n--repository-defaults / --repository <relative-path>. Repository paths are\nworkspace-relative membership keys; absolute paths, escapes, and a repository\nscope for a single-repository workspace are rejected. --repository cannot be\nused without --workspace.", JA: "Config v2 uses explicit scopes: --system, --workspace-defaults,\n--repository-defaults, --workspace <root>, or --workspace <root> together with\n--repository-defaults / --repository <relative-path>. Repository paths are\nworkspace-relative membership keys; absolute paths, escapes, and a repository\nscope for a single-repository workspace are rejected. --repository cannot be\nused without --workspace."},
	"help.config.p4":                {EN: "With --workspace, show every Workspace key that scope can override with its\neffective value and source. --workspace <root> --repository-defaults edits the\nshared repository defaults for that Workspace. A multi-repository Workspace can\nalso edit one membership with --repository <relative-path>. The old flat syntax\nis accepted only for a legacy version-1 file.", JA: "With --workspace, show every Workspace key that scope can override with its\neffective value and source. --workspace <root> --repository-defaults edits the\nshared repository defaults for that Workspace. A multi-repository Workspace can\nalso edit one membership with --repository <relative-path>. The old flat syntax\nis accepted only for a legacy version-1 file."},
	"help.config.p5":                {EN: "A workspace overrides worktree, copy, link, reuse_standby, warm_count, agent.add_dir,\nretention.hot_standby, retention.ended_worktree, discovery.max_depth and\ndiscovery.exclude. warm_count 0 disables replenishment, and so does\nretention.hot_standby 0; reducing the count lets normal GC reclaim unused standby\nslots. reuse_standby controls whether an older READY standby is updated at lease\ntime; the default is true, and false preserves exact-match cold-start behavior.", JA: "A workspace overrides worktree, copy, link, reuse_standby, warm_count, agent.add_dir,\nretention.hot_standby, retention.ended_worktree, discovery.max_depth and\ndiscovery.exclude. warm_count 0 disables replenishment, and so does\nretention.hot_standby 0; reducing the count lets normal GC reclaim unused standby\nslots. reuse_standby controls whether an older READY standby is updated at lease\ntime; the default is true, and false preserves exact-match cold-start behavior."},
	"help.config.p6":                {EN: "A repository overrides default_branch, dir_name, dir_source, cow_min_size_kib,\nprepare.command, prepare.timeout, prepare.version, includes.default_agent_rules,\nreadiness.mode, readiness.early_paths, readiness.timeout, readiness.progress and storage.copy_mode. A\nlease leasing several repositories waits in full mode if any of them asks for it,\nand uses the longest readiness.timeout among them.", JA: "A repository overrides default_branch, dir_name, dir_source, cow_min_size_kib,\nprepare.command, prepare.timeout, prepare.version, includes.default_agent_rules,\nreadiness.mode, readiness.early_paths, readiness.timeout, readiness.progress and storage.copy_mode. A\nlease leasing several repositories waits in full mode if any of them asks for it,\nand uses the longest readiness.timeout among them."},
	"help.config.p7":                {EN: "A list key set on a scope replaces the inherited list instead of extending it. The\nfirst --add copies the parent list as it stands right then, so later changes no longer\nreach that scope; --reset drops the scope list and restores its parent. A repository\nreadiness.early_paths does not apply to the shared workspace root stage of a\nmulti-repository workspace, which keeps using the workspace list.", JA: "A list key set on a scope replaces the inherited list instead of extending it. The\nfirst --add copies the parent list as it stands right then, so later changes no longer\nreach that scope; --reset drops the scope list and restores its parent. A repository\nreadiness.early_paths does not apply to the shared workspace root stage of a\nmulti-repository workspace, which keeps using the workspace list."},
	"help.config.p8":                {EN: "Submodules (repository_defaults.submodules, default true):\nLinked worktrees resolve a submodule's gitdir per worktree, so they cannot reuse\nthe main repository's .git/modules/<name>. wx therefore clones each submodule\nfrom that local module, which stays offline and shares objects as hardlinks. A\nsubmodule is skipped with a warning, leaving the empty gitlink directory, when\nthe local module is absent, when it lacks the gitlink commit, or when no\nupstream url is available; preparation still succeeds. After the clone wx\nrestores the submodule's origin to the upstream url so git push does not write\ninto the main repository's .git/modules. Changing this stops reuse of READY\nstandby worktrees prepared under the previous value.\nCommits made inside a worktree's submodule are lost when the slot is deleted,\nbecause snapshots can only record the gitlink. Push them before releasing.", JA: "Submodules (repository_defaults.submodules, default true):\nLinked worktrees resolve a submodule's gitdir per worktree, so they cannot reuse\nthe main repository's .git/modules/<name>. wx therefore clones each submodule\nfrom that local module, which stays offline and shares objects as hardlinks. A\nsubmodule is skipped with a warning, leaving the empty gitlink directory, when\nthe local module is absent, when it lacks the gitlink commit, or when no\nupstream url is available; preparation still succeeds. After the clone wx\nrestores the submodule's origin to the upstream url so git push does not write\ninto the main repository's .git/modules. Changing this stops reuse of READY\nstandby worktrees prepared under the previous value.\nCommits made inside a worktree's submodule are lost when the slot is deleted,\nbecause snapshots can only record the gitlink. Push them before releasing."},
	"help.config.p9":                {EN: "Agent directories (agent.add_dir):", JA: "Agent directory（agent.add_dir）:"},
	"help.config.always":            {EN: "pass every repository directory under the agent's working directory to --add-dir (default)", JA: "agent の working directory 配下にある全 repository directory を --add-dir に渡す（既定）"},
	"help.config.worktree":          {EN: "pass them only when the agent runs in a wx worktree", JA: "agent が wx worktree で動く場合だけ渡す"},
	"help.config.off":               {EN: "never pass them", JA: "渡さない"},
	"help.config.p10":               {EN: "A workspace with several repositories puts the agent's working directory at the\nparent of those repositories, so their .claude/skills and other agent assets are\nonly loaded when the directories are passed with --add-dir. A workspace that is\na single repository has nothing to pass. Directories you pass yourself are kept.", JA: "複数 repository の workspace では agent の working directory がそれらの親になります。\nそのため .claude/skills などの agent asset は\n--add-dir で directory を渡した場合だけ読み込まれます。workspace が\n単一 repository なら渡すものはありません。自分で渡した directory は保持します。"},
	"help.config.p11":               {EN: "Copy mode (repository_defaults.storage.copy_mode):", JA: "Copy mode (repository_defaults.storage.copy_mode):"},
	"help.config.auto":              {EN: "share identical checked-out files with APFS CoW; fall back to copies, but quarantine when ownership is unprovable (default)", JA: "share identical checked-out files with APFS CoW; fall back to copies, but quarantine when ownership is unprovable (default)"},
	"help.config.cow":               {EN: "fail preparation if CoW fails", JA: "fail preparation if CoW fails"},
	"help.config.copy":              {EN: "keep normal Git checkout files", JA: "keep normal Git checkout files"},
	"help.config.p12":               {EN: "repository_defaults.cow_min_size_kib sets the smallest file CoW shares, in KiB (default 16).\nFiles below it keep their normal checkout copy; 0 shares every eligible file, and\na larger value trades disk savings for less per-file work. Changing it stops\nreuse of READY standby worktrees prepared under the previous value.\nA repository can override the limit and the copy mode with wx config --workspace\n<root> --repository <relative-path>, since the best values depend on the\nrepository's file size distribution and checkout. Only the repositories whose\neffective values changed lose the reuse of their READY standby worktrees. A\n--config override on a single lease wins over both the repository entry and the\nglobal setting.", JA: "repository_defaults.cow_min_size_kib sets the smallest file CoW shares, in KiB (default 16).\nFiles below it keep their normal checkout copy; 0 shares every eligible file, and\na larger value trades disk savings for less per-file work. Changing it stops\nreuse of READY standby worktrees prepared under the previous value.\nA repository can override the limit and the copy mode with wx config --workspace\n<root> --repository <relative-path>, since the best values depend on the\nrepository's file size distribution and checkout. Only the repositories whose\neffective values changed lose the reuse of their READY standby worktrees. A\n--config override on a single lease wins over both the repository entry and the\nglobal setting."},
	"help.config.p13":               {EN: "Workspace root files (multi-repository workspaces):\nThe root itself has no checkout, so only these paths reach a slot: AGENTS.md,\nAGENTS.local.md, CLAUDE.md, CLAUDE.local.md, the agent asset directories\n.claude/skills, .claude/agents, .claude/commands, .claude/hooks and\n.codex/prompts, and whatever the rules below add. Missing paths are skipped.\nAdd more with a .worktreeinclude (copied, glob patterns, no match is fine) and a\n.worktreelink (symlinked back to the root, literal paths that must exist) in the\nroot itself, or with wx config --workspace <root> copy --add and link --add. A\ncopy path set in the config must exist or preparation fails. A path cannot be both copied and linked. The root manifests\napply to multi-repository workspaces only; inside a repository the same file\nnames keep their repository meaning.", JA: "Workspace root files（multi-repository workspace）:\nroot 自体には checkout がないため、slot へ届く path は AGENTS.md、\nAGENTS.local.md、CLAUDE.md、CLAUDE.local.md、agent asset directory\n.claude/skills、.claude/agents、.claude/commands、.claude/hooks と\n.codex/prompts と、下記の規則が追加する path です。存在しない path は省略します。\n.worktreeinclude（copy、glob は no match 可）と\n.worktreelink（root へ symlink、存在必須の literal path）を\nroot itself, or with wx config --workspace <root> copy --add and link --add. A\n設定した copy path は存在しないと準備に失敗します。path は copy と link の両方にはできません。root manifest は\nmulti-repository workspace にだけ適用し、repository 内では同じ file\n名が repository 本来の意味を保ちます。"},
	"help.config.p14":               {EN: "Readiness (readiness.mode):", JA: "Readiness (readiness.mode):"},
	"help.config.early":             {EN: "wait for Git registration and startup files, then launch with readiness hooks (default)", JA: "wait for Git registration and startup files, then launch with readiness hooks (default)"},
	"help.config.full":              {EN: "wait for checkout, includes, links, prepare commands, and final validation", JA: "wait for checkout, includes, links, prepare commands, and final validation"},
	"help.config.p15":               {EN: "Without readiness hooks, both modes wait for full preparation. Resume and shell/run/new always wait for full preparation.\nUse full when checkout hooks or prepare commands generate or update startup settings.\nreadiness.early_paths adds literal repository-relative paths to the startup list;\nedit it with wx config --repository-defaults readiness.early_paths\n--add/--remove/--reset, or per repository with wx config --workspace <root>\n--repository <relative-path> readiness.early_paths --add.\nDirectories include their descendants; no glob patterns are expanded. Only paths\nalready scheduled by checkout or copy/link rules are materialized. Workspace roots\nuse the same selection. Absolute paths, escapes, the root itself, and .git are rejected.\nreadiness.progress prints the preparation progress to stderr while a lease waits\n(default true); set it to false to wait without any output. A non-terminal stderr\nnever gets the progress lines, whatever the setting says.", JA: "Without readiness hooks, both modes wait for full preparation. Resume and shell/run/new always wait for full preparation.\nUse full when checkout hooks or prepare commands generate or update startup settings.\nreadiness.early_paths adds literal repository-relative paths to the startup list;\nedit it with wx config --repository-defaults readiness.early_paths\n--add/--remove/--reset, or per repository with wx config --workspace <root>\n--repository <relative-path> readiness.early_paths --add.\nDirectories include their descendants; no glob patterns are expanded. Only paths\nalready scheduled by checkout or copy/link rules are materialized. Workspace roots\nuse the same selection. Absolute paths, escapes, the root itself, and .git are rejected.\nreadiness.progress prints the preparation progress to stderr while a lease waits\n(default true); set it to false to wait without any output. A non-terminal stderr\nnever gets the progress lines, whatever the setting says."},
	"help.resume.p1":                {EN: "Restore an archived wx session into a new managed workspace.\nWith --fresh, keep the conversation but build the worktree from the current base.\nUse --branch with --fresh to choose the detached base.", JA: "アーカイブ済み wx session を新しい管理 workspace へ復元します。\n--fresh では会話を保持し、現在の base から worktree を作成します。\n--fresh と --branch で detached base を選択します。"},
	"help.shell.p1":                 {EN: "Open a shell in a managed wx workspace. This is the way to work in an isolated\nworktree yourself, without launching an agent.", JA: "管理された wx workspace で shell を開きます。agent を起動せず隔離された\nworktree で自分で作業するためのコマンドです。"},
	"help.shell.p2":                 {EN: "The workspace is prepared the same way it is for wx claude and wx codex, and it\nis returned when the shell exits: unfinished work is saved first, and the\nworktree stays for retention.ended_worktree so wx shell --resume <id> brings it\nback. wx clear --all can also ask the shell to stop.", JA: "workspace は wx claude / wx codex と同じ方法で準備され、\nshell 終了時に返却されます。未完了の作業は先に保存され、\nworktree stays for retention.ended_worktree so wx shell --resume <id> brings it\nback. wx clear --all can also ask the shell to stop."},
	"help.shell.p3":                 {EN: "--resume only accepts sessions leased by wx shell, wx run, or wx new. Resume a\nsession started by an agent with wx resume <wx-session-id> [claude|codex].", JA: "--resume は wx shell、wx run、wx new が貸し出した session だけを受け付けます。agent が開始した session は wx resume <wx-session-id> [claude|codex] で再開します。"},
	"help.shell.p4":                 {EN: "The worktree is detached, as it is for every wx workspace; --branch only\nchooses the base commit, and creating or pushing a branch is left to you. The\nshell comes from lease.shell, then $SHELL, then /bin/sh.", JA: "worktree は全 wx workspace と同じく detached です。--branch は base commit だけを選び、branch の作成や push は利用者が行います。shell は lease.shell、次に $SHELL、最後に /bin/sh から選びます。"},
	"help.shell.p5":                 {EN: "Options:", JA: "オプション:"},
	"help.shell.branch":             {EN: "choose a detached base (repeatable)", JA: "detached base を選択（複数指定可）"},
	"help.shell.resume":             {EN: "restore the worktree of an earlier wx session", JA: "restore the worktree of an earlier wx session"},
	"help.run.p1":                   {EN: "Run one command in a managed wx workspace and exit with its status. Use it to\nrun a build or a test suite against an isolated worktree without disturbing the\ncurrent one.", JA: "管理された wx workspace でコマンドを1つ実行し、その終了 status で終了します。\n隔離された workspace で build や test suite を実行するために使います。 worktree を現在の\ncurrent one."},
	"help.run.p2":                   {EN: "The workspace is returned when the command exits, and the same saving and\nretention as wx shell apply, so wx shell --resume <id> can reopen what the\ncommand left behind.", JA: "command 終了時に workspace を返却し、保存と retention は wx shell と同じです。wx shell --resume <id> で command が残した内容を再開できます。"},
	"help.run.p3":                   {EN: "--resume only accepts sessions leased by wx shell, wx run, or wx new. Resume a\nsession started by an agent with wx resume <wx-session-id> [claude|codex].", JA: "--resume は wx shell、wx run、wx new が貸し出した session だけを受け付けます。agent が開始した session は wx resume <wx-session-id> [claude|codex] で再開します。"},
	"help.run.p4":                   {EN: "The command runs at the top of the workspace even when wx run is invoked from a\nsubdirectory; the original directory is passed as WX_SOURCE_CWD.", JA: "wx run を subdirectory から呼んでも command は workspace の top で実行し、元の directory は WX_SOURCE_CWD として渡します。"},
	"help.run.p5":                   {EN: "Options:", JA: "オプション:"},
	"help.run.branch":               {EN: "choose a detached base (repeatable)", JA: "detached base を選択（複数指定可）"},
	"help.run.resume":               {EN: "restore the worktree of an earlier wx session", JA: "restore the worktree of an earlier wx session"},
	"help.new.p1":                   {EN: "Lease a managed wx workspace and print its path on one line. Nothing is\nstarted in it, so this is how an agent prepares a worktree to hand to a\nSubAgent.", JA: "管理された wx workspace を貸し出し、path を1行で表示します。何も\n起動しないため、agent が SubAgent に渡す worktree を準備する方法です。\nSubAgent。"},
	"help.new.p2":                   {EN: "The lease does NOT follow the process that asked for it: wx new sends no\nheartbeat, so the workspace is not reclaimed when the caller exits. It is\nreturned when the wx session that ran wx new ends, when wx release <id> is\nrun, or when lease.ttl has passed, whichever comes first.\nWithout one of the first two, the workspace stays leased until that deadline.", JA: "lease は要求元の process には追従しません。wx new は heartbeat を送らないため、\ncaller 終了時に workspace は回収されません。\nwx new を実行した wx session の終了、wx release <id> の実行、lease.ttl の経過のいずれかで返却されます。\n前の2つを行わない場合、workspace はその期限まで貸出中のままです。"},
	"help.new.p3":                   {EN: "Expiry saves before it returns the lease, and nothing edits the worktree\nafterwards, so work written after the deadline is not saved. Return the lease\nwith wx release <id> when the SubAgent is done rather than relying on the\ndeadline.", JA: "期限切れでは lease を返す前に保存し、その後 worktree は編集しません。\n期限後に書き込んだ作業は保存されません。期限に頼らず、SubAgent が終わったら wx release <id> で返却してください。"},
	"help.new.p4":                   {EN: "The session id to pass to wx release and wx shell --resume is shown by wx\nslots, or by --json here.", JA: "wx release と wx shell --resume に渡す session id は wx slots または\nここで --json を指定すると表示されます。"},
	"help.new.p5":                   {EN: "Options:", JA: "オプション:"},
	"help.new.branch":               {EN: "choose a detached base (repeatable)", JA: "detached base を選択（複数指定可）"},
	"help.new.json":                 {EN: "print the session id and path as JSON", JA: "session id と path を JSON で表示"},
	"help.release.p1":               {EN: "Return a workspace leased by wx new without waiting for lease.ttl. Unfinished\nwork is saved first, and the worktree stays for retention.ended_worktree so\nwx shell --resume <id> can reopen it.", JA: "wx new で貸し出した workspace を lease.ttl を待たずに返却します。未完了の\n作業は先に保存し、worktree は retention.ended_worktree の間残るため、\nwx shell --resume <id> で再開できます。"},
	"help.release.p2":               {EN: "With --discard the work is not saved: the return schedules the worktree for\nremoval instead, so nothing is left to reopen with wx shell --resume.", JA: "--discard では作業を保存せず、返却時に worktree を\n削除対象にするため、wx shell --resume で再開するものは残りません。"},
	"help.release.p3":               {EN: "Only leases with no running process are returned this way. A workspace held by\nwx shell or wx run is returned when that shell or command exits, and one held\nby an agent when that agent exits; wx clear --all asks either of them to stop.", JA: "実行中 process がない lease だけをこの方法で返却します。workspace を保持する\nwx shell / wx run は shell または command の終了時、保持する\nagent は agent 終了時に返却されます。wx clear --all はいずれにも停止を求めます。"},
	"help.release.p4":               {EN: "Options:", JA: "オプション:"},
	"help.release.discard":          {EN: "return the lease without saving unfinished work, and remove the\nworktree instead of keeping it for retention.ended_worktree", JA: "未保存の作業を保存せず貸出を返却し、\nworktree を retention.ended_worktree に残さず削除"},
	"help.slots.p1":                 {EN: "List managed wx slots with their repository, session, copy mode, and disk usage.\nAGENT names what holds the slot: claude or codex for an agent, and wx-shell,\nwx-run, or wx-path for a workspace leased by wx shell, wx run, or wx new.\nEvery slot that still occupies disk is listed, so the SIZE(MB) column covers the\nsame slots as the Disk line of wx status. REPO names the source repositories the\nslot was prepared from; a multi-repo workspace lists them separated by commas.", JA: "管理 wx slot の repository、session、copy mode、ディスク使用量を一覧表示します。\nAGENT names what holds the slot: claude or codex for an agent, and wx-shell,\nwx-run, or wx-path for a workspace leased by wx shell, wx run, or wx new.\nEvery slot that still occupies disk is listed, so the SIZE(MB) column covers the\nsame slots as the Disk line of wx status. REPO names the source repositories the\nslot was prepared from; a multi-repo workspace lists them separated by commas."},
	"help.slots.p2":                 {EN: "SIZE(MB) is what the slot occupies on its own, rounded up: blocks it still\nshares with the main worktree are excluded, so the column sums without double\ncounting. COPY reports what the slot looks like now: cow once any file still\nshares blocks with the main worktree, copy otherwise.", JA: "SIZE(MB) は slot 単独の占有量を切り上げた値です。main worktree と共有する block は除外するため二重計上せず合計できます。COPY は現在の状態を示し、1 file でも block を共有していれば cow、そうでなければ copy です。"},
	"help.slots.p3":                 {EN: "The daemon measures a slot when its preparation finishes and re-measures every\nroot periodically; wx slots only reads those results, never measures on demand.\nRows still waiting for the first measurement show pending, and platforms that\ncannot compare blocks show unsupported. --json carries the measurement time.", JA: "The daemon measures a slot when its preparation finishes and re-measures every\nroot periodically; wx slots only reads those results, never measures on demand.\nRows still waiting for the first measurement show pending, and platforms that\ncannot compare blocks show unsupported. --json carries the measurement time."},
	"help.slots.p4":                 {EN: "--json adds the lease kind, the time the lease expires, and the wx session\nthat asked for a wx new lease.", JA: "--json adds the lease kind, the time the lease expires, and the wx session\nthat asked for a wx new lease."},
	"help.slots.p5":                 {EN: "Options:", JA: "オプション:"},
	"help.slots.all":                {EN: "also list sessions that no longer hold a slot", JA: "also list sessions that no longer hold a slot"},
	"help.slots.json":               {EN: "print machine-readable JSON", JA: "機械可読 JSON を表示"},
	"help.bench.p1":                 {EN: "Measure how long the current workspace takes to become usable, and where that\ntime goes. Each run leases a workspace the way wx new does, waits for EARLY\nREADY and then for FULL READY, prints the breakdown the daemon recorded for\nthat preparation, and returns the lease without saving it.", JA: "現在の workspace が使えるようになるまでの時間と、その内訳を計測します。\n内訳を計測します。各 run は wx new と同じように workspace を貸し出し、EARLY\nREADY、続いて FULL READY を待ち、daemon が記録した準備の内訳を\n表示して保存せず lease を返却します。"},
	"help.bench.p2":                 {EN: "EARLY READY is the point an agent can start: Git registration and the startup\nfiles are in place. FULL READY adds the remaining checkout, the includes and\nlinks, the prepare command, CoW sharing, and the final validation. Both are\nmeasured from the lease request, so they include the time the request waited\nfor a job slot.", JA: "EARLY READY は agent を開始できる時点で、Git 登録と startup file が揃っています。FULL READY では残りの checkout、include/link、prepare command、CoW sharing、最終検証も完了します。どちらも lease 要求から計測するため、job slot 待ち時間を含みます。"},
	"help.bench.p3":                 {EN: "By default the standby worktrees waiting for the current workspace are retired\nfirst, so what is measured is a cold start. They are reclaimed by normal GC and\nreplenished afterwards. With --reuse nothing is retired and the run measures\nwhatever the pool returns, which is reported as warm when a prepared slot was\nhanded over with no preparation to measure.", JA: "既定では現在の workspace を待つ standby worktree を先に退役させ、cold start を計測します。通常の GC で回収した後に補充します。--reuse では退役させず pool が返したものを計測し、準備なしで渡された slot は warm と報告します。"},
	"help.bench.p4":                 {EN: "The breakdown comes from the running daemon and is not persisted, so restarting\nthe daemon between the preparation and the report loses it. Phase names that\ncontain a dot, such as cow.compare, are totals across the parallel workers of\nthat phase and can exceed the wall-clock time of the phase above them.", JA: "内訳は稼働中 daemon から取得し永続化しないため、準備後・表示前に daemon を再起動すると失われます。cow.compare のように dot を含む phase 名は並列 worker の合計で、上位 phase の経過時間を超えることがあります。"},
	"help.bench.p5":                 {EN: "With --runs, wx waits for the saving, removal, and replenishment jobs of the\nprevious run to finish before measuring the next one, and prints the minimum,\nmedian, and maximum at the end. A single successful run has no distribution to\nsummarize, so its measured time is printed on its own, both in that summary and\nin the comparison table.", JA: "--runs では前の run の保存・削除・補充 job が終わってから次を計測し、最後に最小・中央値・最大を表示します。成功 run が1件だけなら分布を作らず、その計測値を概要と比較表に単独表示します。"},
	"help.bench.p6":                 {EN: "--sweep measures the settings a search for the best CoW threshold usually\ncompares: copy_mode=copy as the baseline without CoW sharing, then\ncow_min_size_kib of 0, 4, 8, 16, 32, 64, and 128, each with the copy mode the\ndaemon is running with. It is the same measurement as passing those eight\nvalues as --config by hand, so the two options are rejected together.", JA: "--sweep は最適な CoW threshold の探索で比較する設定を計測します。CoW なしの copy_mode=copy を基準に、cow_min_size_kib の 0、4、8、16、32、64、128 を daemon の copy mode ごとに測ります。8値を --config で指定する場合と同じため、2つの option は併用できません。"},
	"help.bench.p7":                 {EN: "Repeat --config to compare preparation settings of your own. Each --config is\none configuration to measure, written as copy_mode=<auto|cow|copy> and\ncow_min_size_kib=<n> separated by commas; the keys you leave out keep the value\nthe daemon is running with.", JA: "--config を繰り返して独自の準備設定を比較できます。各 --config は1つの設定で、copy_mode=<auto|cow|copy> と cow_min_size_kib=<n> を comma 区切りで書きます。省略した key は daemon の実効値を使います。"},
	"help.bench.p8":                 {EN: "Every configuration is measured --runs times, and the comparison table adds the\ndisk each configuration left behind: the exclusive size is what the slot\noccupies after CoW sharing is discounted, taken from the same measurement wx\nslots reports. A configuration whose usage is not measured before the lease is\nreturned is reported as - and keeps its timings. A single run per configuration\nis one sample of a machine under changing load, so settings whose min and max\noverlap are separated by measuring again with a larger --runs. The settings\ntravel with the lease request and apply only to the slot prepared for it: wx\nneither reads nor writes your configuration file, and the daemon keeps\npreparing every other workspace with its own settings. Interrupting the command\ntherefore leaves no measurement setting behind. Slots prepared for a\nconfiguration are not handed to later leases or kept as standby, so each\nconfiguration is always measured as a cold start, and both --sweep and --config\nare rejected together with --reuse.", JA: "各設定を --runs 回計測し、比較表には設定後の disk も追加します。exclusive size は CoW sharing を差し引いた slot 占有量で、wx slots と同じ計測値です。lease 返却前に usage を計測できなかった設定は - と表示し、時間は残します。設定ごとに1 run は負荷変動下の1サンプルなので、min/max が重なる設定は --runs を増やして再計測します。設定は lease 要求とともに送られ、その slot にだけ適用します。wx は設定ファイルを読み書きせず、他 workspace は独自設定で準備します。中断しても計測設定は残りません。設定用 slot は後続 lease や standby に回さないため常に cold start を測り、--sweep と --config は --reuse と併用できません。"},
	"help.bench.p9":                 {EN: "The measured workspace is returned without saving it, as wx release --discard\ndoes. Interrupting wx bench skips that return, and the workspace then stays\nleased until the wx session that ran the command ends, or until lease.ttl.", JA: "計測した workspace は wx release --discard と同じく保存せず返却します。wx bench を中断すると返却を省略し、コマンドを実行した wx session の終了または lease.ttl まで貸出中のままです。"},
	"help.bench.p10":                {EN: "Exit status is 0 when every run finished, 1 when one of them failed, and 2 for\nan argument error.", JA: "全 run 完了時は終了コード0、1件でも失敗すれば1、引数エラーなら2です。"},
	"help.bench.p11":                {EN: "Options:", JA: "オプション:"},
	"help.bench.runs":               {EN: "measure this many leases (default 1)", JA: "measure this many leases (default 1)"},
	"help.bench.branch":             {EN: "choose a detached base (repeatable)", JA: "detached base を選択（複数指定可）"},
	"help.bench.sweep":              {EN: "compare copy_mode=copy and cow_min_size_kib\n0/4/8/16/32/64/128", JA: "compare copy_mode=copy and cow_min_size_kib\n0/4/8/16/32/64/128"},
	"help.bench.config":             {EN: "compare this preparation setting; keys are\ncopy_mode and cow_min_size_kib (repeatable)", JA: "compare this preparation setting; keys are\ncopy_mode and cow_min_size_kib (repeatable)"},
	"help.bench.reuse":              {EN: "keep standby worktrees and measure what the\npool returns", JA: "keep standby worktrees and measure what the\npool returns"},
	"help.bench.json":               {EN: "print machine-readable JSON", JA: "機械可読 JSON を表示"},
	"help.discard_recovery.p1":      {EN: "Discard the recovery state of the sessions whose recovery refs are gone from\nthe source repository, so that workspace stops being reported by wx doctor and\ncan be forgotten.", JA: "復旧 ref が source repository から消えた session の復旧状態を破棄し、\nwx doctor の報告対象から workspace を外して\n管理を解除できるようにします。"},
	"help.discard_recovery.p2":      {EN: "A recovery ref disappears when the source repository is deleted and recreated\nat the same path. wx then quarantines the snapshots that recorded those refs,\nand they can no longer restore anything. This command deletes those snapshot\nrecords, ends their sessions, and deletes the worktrees of the slots they\nquarantined, unsaved work included. Sessions of other workspaces, and every\nsession that still has its refs, are left alone. Run --dry-run first to see\nthe sessions and worktree paths that would go.", JA: "source repository を同じ path で削除・再作成すると recovery ref が消えます。wx はその ref を記録した snapshot を隔離し、復元できなくします。この command は snapshot record を削除し、session を終了し、隔離した slot の worktree（未保存の作業を含む）を削除します。他 workspace の session と、ref が残る session はそのままです。先に --dry-run で対象 session と worktree path を確認してください。"},
	"help.discard_recovery.p3":      {EN: "Options:", JA: "オプション:"},
	"help.discard_recovery.dry_run": {EN: "list what would be discarded without changing anything", JA: "list what would be discarded 変更せずに"},
	"help.forget.p1":                {EN: "Stop managing a workspace, reclaiming the worktrees wx still owns for it.", JA: "workspace の管理を解除し、wx が保持している worktree を回収します。"},
	"help.forget.p2":                {EN: "Standby worktrees are reclaimed on the way out: they hold no work of yours.\nA workspace that is still in use is refused, whatever the flags: end its\nsessions, or run wx release <id>, and run wx forget again.", JA: "standby worktree は利用者の作業を持たないため、解除の過程で回収します。使用中の workspace は flag にかかわらず拒否するので、session を終了するか wx release <id> を実行してから wx forget をもう一度実行してください。"},
	"help.forget.p3":                {EN: "Recovery state is kept, and the workspace is refused until you say to throw it\naway. That state is the released sessions wx can still restore, their snapshots\nand the recovery refs in the source repository, and the worktrees of the\nsessions that were quarantined because their refs are gone. The refusal counts\nwhat is there. --discard-recovery deletes all of it, unsaved work included, and\nthen forgets the workspace.", JA: "復旧状態は保持し、破棄を指示するまで workspace の解除を拒否します。復旧状態とは、wx がまだ復元できる返却済み session と、その snapshot および source repository 内の recovery ref、さらに ref が消えたため隔離された session の worktree です。拒否の際にはその件数を表示します。--discard-recovery はそれらを未保存の作業ごと削除してから workspace の管理を解除します。"},
	"help.forget.p4":                {EN: "Options:", JA: "オプション:"},
	"help.forget.discard_recovery":  {EN: "discard the recovery state of this workspace instead of\nrefusing to forget it", JA: "discard the recovery state of this workspace instead of\nrefusing to forget it"},
	"help.daemon.p1":                {EN: "Change whether the daemon is running, or install and remove the per-user\nLaunchAgent that starts it at login.", JA: "daemon の稼働状態を変更するか、ユーザー単位の\nlogin 時に起動する LaunchAgent をインストール・削除します。"},
	"help.daemon.start":             {EN: "run the daemon, or report that it is already running", JA: "run the daemon, or report that it is すでに起動しています"},
	"help.daemon.stop":              {EN: "exit the running daemon, leaving the LaunchAgent registered", JA: "稼働中の daemon を終了（LaunchAgent は登録したまま）"},
	"help.daemon.restart":           {EN: "replace the running daemon so a new wx binary takes effect", JA: "稼働中の daemon を置き換え、新しい wx binary を有効化"},
	"help.daemon.install":           {EN: "write the LaunchAgent plist and load it", JA: "LaunchAgent plist を書き込み読み込む"},
	"help.daemon.uninstall":         {EN: "unload the LaunchAgent and remove its plist", JA: "LaunchAgent を解除し plist を削除"},
	"help.daemon.p2":                {EN: "start, stop, and restart wait for the daemon to reach the requested state and\ngive up after 60s. The daemon acts only once it is idle, so none of them cuts\nshort a request or a job that is already running.", JA: "start, stop, and restart wait for the daemon to reach the requested state and\ngive up after 60s. The daemon acts only once it is idle, so none of them cuts\nshort a request or a job that is すでに起動しています."},
	"help.daemon.p3":                {EN: "Options:", JA: "オプション:"},
	"help.daemon.foreground":        {EN: "with start, serve in this process instead of asking launchd\nto start the daemon. This is how the LaunchAgent runs wx.", JA: "with start, serve in this process instead of asking launchd\nto daemon を起動. This is how the LaunchAgent runs wx."},
	"help.setup.p1":                 {EN: "Walk through what wx needs to run on its own and apply the choices. Each item\nis offered with the choices its current state allows, so running setup again\nafter a completed setup changes nothing.", JA: "wx が単独で動くために必要な項目を確認し、選択を適用します。各項目は\n現在の状態で選べる操作だけを提示するため、setup を再実行しても\n完了済みの設定は変わりません。"},
	"help.setup.p2":                 {EN: "The items are the prerequisites, storage.worktree_root, the shell PATH entry,\nthe LaunchAgent, the Claude and Codex hook entries, and the daemon. wx owns\nthe wx entries of the agent hook configuration: it writes a dedicated group\nper event and never touches the rest of the file.", JA: "The items are the prerequisites, storage.worktree_root, the shell PATH entry,\nthe LaunchAgent, the Claude and Codex hook entries, and the daemon. wx owns\nthe wx entries of the agent hook configuration: it writes a dedicated group\nper event and never touches the rest of the file."},
	"help.setup.p3":                 {EN: "Cancelling stops the walk without undoing what was already applied; every item\nis idempotent, so running wx setup again finishes the rest.", JA: "キャンセルすると適用済みを戻さず walk を停止します。各項目は冪等なので wx setup を再実行すれば残りを完了できます。"},
	"help.setup.p4":                 {EN: "--remove deletes what wx setup writes instead of asking: the wx hook entries,\nthe LaunchAgent, and the configuration file. Removing the LaunchAgent boots the\ndaemon out, so run anything that needs the daemon, such as wx clear, first. The\nshell startup file is left alone: wx cannot tell its own PATH line apart from\none you wrote or one your dotfile manager owns, so remove that line yourself.\nThe state database, the log directory, and the worktree root are kept too\nbecause they hold saved work and records; each is printed on a line starting\nwith \"leftover\" so a script can act on them. The uninstaller runs this.", JA: "--remove は質問せず wx setup の書き込み（wx hook entry、LaunchAgent、設定ファイル）を削除します。LaunchAgent を解除すると daemon が停止するため、wx clear など daemon が必要な操作を先に実行してください。shell startup file は残します。自分の PATH 行や dotfile manager の行と区別できないため、利用者が削除してください。state database、log directory、worktree root も保存済み作業と記録を含むため残し、script が扱えるよう各 path を `leftover` で始まる行に表示します。uninstaller はこれを実行します。"},
	"help.setup.p5":                 {EN: "Exit status is 0 when the walk finished, 1 when an item could not be applied,\nthe walk was cancelled, or no terminal is attached, and 2 for an argument\nerror. --check reports differences with status 0. --update does not use the\nexit status to report a missing terminal: it names the items that need\nattention on stderr and exits 0. --remove needs no terminal, keeps going after\na failed item, and exits 1 when any item failed.", JA: "walk 完了時の終了コードは0、適用できない項目・キャンセル・端末なしは1、引数エラーは2です。--check は差分があっても0です。--update は端末なしを終了コードで示さず、対応が必要な項目を stderr に出して0で終了します。--remove は端末不要で、失敗後も続行し、失敗があれば1で終了します。"},
	"help.setup.p6":                 {EN: "Options:", JA: "オプション:"},
	"help.setup.check":              {EN: "report the current state and change nothing; needs no terminal", JA: "report the current state and change nothing; needs no terminal"},
	"help.setup.json":               {EN: "with --check, print machine-readable JSON", JA: "with --check, 機械可読 JSON を表示"},
	"help.setup.update":             {EN: "offer only the items that no longer match what wx would write, and\nprint nothing when there are none. The installer runs this.", JA: "offer only the items that no longer match what wx would write, and\nprint nothing when there are none. The installer runs this."},
	"help.setup.remove":             {EN: "delete the configuration wx setup writes and report what was kept", JA: "delete the configuration wx setup writes and report what was kept"},
	"help.setup.item":               {EN: "configure only this item (for example hooks.claude)", JA: "configure only this item (for example hooks.claude)"},
	"help.setup.action":             {EN: "apply one action offered for --item by wx setup --check", JA: "apply one action offered for --item by wx setup --check"},
	"help.setup.value":              {EN: "value used by the manual action", JA: "value used by the manual action"},
	"help.hook.p1":                  {EN: "Run a wx agent hook event read from stdin. Invoked by agent hook\nconfiguration, not normally run directly.", JA: "stdin から wx agent hook event を読み取って実行します。agent hook の\n設定から呼び出され、通常は直接実行しません。"},
}
